import json
d=json.load(open('row133.json'))
r=d['rows'][0]['row']
msgs=r['messages']
with open('transcript.txt','w') as f:
    for i,m in enumerate(msgs):
        f.write('='*80+'\n')
        f.write('IDX %d | ROLE %s | TS %s\n'%(i,m['role'],m.get('timestamp')))
        if m.get('thinking'):
            f.write('--- THINKING ---\n'+m['thinking']+'\n')
        if m.get('content'):
            f.write('--- CONTENT ---\n'+m['content']+'\n')
        if m.get('tool_uses'):
            for t in m['tool_uses']:
                f.write('--- TOOL: %s ---\n'%t['tool'])
                f.write(t['input']+'\n')
print('done')
